# pf-ladder, 13 Oct 2026.  Checks behind PROOF.md (ladder of certificates).  Pure Python, exact arithmetic.
#   A. support facts used by Theorem D (depth-width): every direction dir z (z != 0) has exactly 2 nonzeros per column,
#      the kernel K = dir e1 ... dir em has 2^m nonzeros in every column, free letters are monomial;
#      sample words with j < m directions have <= 2^j nonzeros per column (illustration; the lemma is proved).
#   B. m = 2, engine game: 0-1 BFS over the group generated by the letters: least number of directions in a
#      word equal to K (expect 2), and the size of the group (consistency of the frame picture).
#   C. table: units W-in-M with W*L_m <= M < W+m-1 (open under the certified rung-1 bound, closed by Theorem D).
#   D. barrier arithmetic: filtered rung (j >= 1) on the open targets; pair-potential ceiling sqrt(2m+1)-1.
# Matrices: entries are Gaussian integers after scaling by 2 per direction: 2*dir z = (1+i) I + (1-i) X^z.
import itertools, math, random, sys
from fractions import Fraction as Fr
from collections import deque

def gmul(A, B):
    n = len(A)
    return tuple(tuple(sum(A[r][k] * B[k][c] for k in range(n)) for c in range(n)) for r in range(n))

def dir2(m, z):           # 2 * dir z, Gaussian-integer entries (Python complex with integer parts: exact)
    n = 1 << m
    M = [[0j] * n for _ in range(n)]
    for x in range(n):
        M[x][x] += (1 + 1j); M[x ^ z][x] += (1 - 1j)
    return tuple(tuple(r) for r in M)

def nnz_cols(M):
    n = len(M)
    return [sum(1 for r in range(n) if M[r][c] != 0) for c in range(n)]

def perm_mat(n, p):       # (P v)(x) = v(p(x))  -> P[x][p(x)] = 1
    M = [[0j] * n for _ in range(n)]
    for x in range(n): M[x][p[x]] = 1
    return tuple(tuple(r) for r in M)

def diag_mat(d):
    n = len(d)
    return tuple(tuple(d[r] if r == c else 0j for c in range(n)) for r in range(n))

I4 = [1, 1j, -1, -1j]

def partA():
    print("A. support facts")
    for m in range(1, 9):
        n = 1 << m
        ok_dir = all(set(nnz_cols(dir2(m, z))) == {2} for z in range(1, n)) if m <= 6 else \
                 all(set(nnz_cols(dir2(m, z))) == {2} for z in random.Random(m).sample(range(1, n), 8))
        K = dir2(m, 1)
        for j in range(1, m): K = gmul(K, dir2(m, 1 << j))
        full = set(nnz_cols(K)) == {n}
        print(f"  m={m}: every dir z (z!=0) has exactly 2 nonzeros per column: {ok_dir}"
              f"{'' if m <= 6 else ' (8 sampled z)'} ; K has {n} nonzeros in every column: {full}")
    # words with j < m directions and random free letters (random permutations = widened game, random Z4 phases)
    rng = random.Random(1)
    for m in (3, 4):
        n = 1 << m; worst = {}
        for trial in range(200):
            j = rng.randrange(0, m)
            W = perm_mat(n, list(range(n)))
            for _ in range(j):
                p = list(range(n)); rng.shuffle(p)
                W = gmul(perm_mat(n, p), W)
                W = gmul(diag_mat([I4[rng.randrange(4)] for _ in range(n)]), W)
                W = gmul(dir2(m, rng.randrange(1, n)), W)
            p = list(range(n)); rng.shuffle(p)
            W = gmul(perm_mat(n, p), W)
            worst[j] = max(worst.get(j, 0), max(nnz_cols(W)))
        print(f"  m={m}: 200 random words (all permutations, Z4 phases): max nonzeros per column by number of "
              f"directions j: {dict(sorted(worst.items()))}  (bound 2^j; K needs {n})")


def partB():
    print("B. m = 2, engine game: 0-1 BFS (free letters cost 0, a direction costs 1)")
    m, n = 2, 4
    # work with true matrices: entries in Z[i][1/2]; keep pairs (2^k * M, k) normalised so that the key is unique:
    # since |det dir| = 1 and dir is unitary, use floats? no: exact via scaling by 2 per direction and reducing.
    def red(M, k):
        while k > 0 and all((e.real % 2 == 0 and e.imag % 2 == 0) for r in M for e in r):
            M = tuple(tuple(e / 2 for e in r) for r in M); k -= 1
        return (M, k)
    free = []                                            # generators of the engine's free group at m = 2
    for z in (1, 2):                                     # shifts X^e1, X^e2
        free.append(perm_mat(n, [x ^ z for x in range(n)]))
    free.append(perm_mat(n, [((x & 1) << 1) | (x >> 1) for x in range(n)]))        # swap the two address bits
    free.append(perm_mat(n, [x ^ ((x & 1) << 1) for x in range(n)]))               # transvection b2 += b1
    for z in range(1, n):                                # phaseMat z 0 = diag i^(z.x); products give i^Q(x)
        free.append(diag_mat([I4[bin(z & x).count('1') % 4] for x in range(n)]))
    free.append(diag_mat([1j] * n))                      # phaseMat 0 1 = the scalar i
    dirs = [dir2(m, z) for z in range(1, n)]
    K = gmul(dir2(m, 1), dir2(m, 2))
    Kkey = red(K, 2)
    start = red(perm_mat(n, list(range(n))), 0)
    dist = {start: 0}; dq = deque([start])
    while dq:                                            # 0-1 BFS: free edges cost 0, direction edges cost 1
        key = dq.popleft(); M, k = key; dcur = dist[key]
        for f in free:
            nk = red(gmul(f, M), k)
            if dist.get(nk, 10**9) > dcur:
                dist[nk] = dcur; dq.appendleft(nk)
        for D in dirs:
            nk = red(gmul(D, M), k + 1)
            if dist.get(nk, 10**9) > dcur + 1:
                dist[nk] = dcur + 1; dq.append(nk)
    hist = {}
    for v in dist.values(): hist[v] = hist.get(v, 0) + 1
    print(f"  group elements reached: {len(dist)} ; by least number of directions: {dict(sorted(hist.items()))}")
    print(f"  least number of directions in a word equal to K: {dist.get(Kkey)}  (Theorem D / depth: m = 2)")

# certified rung-1 bounds L_m (moves per array), from wave16/b56-note/NOTE.md
L = {2: {'engine': Fr(2), 'widened': Fr(2)},
     3: {'engine': Fr(14, 5), 'widened': Fr(14, 5)},
     4: {'engine': Fr(41, 13), 'widened': Fr(41, 13)},
     5: {'engine': Fr(11738925, 4404165), 'widened': Fr(31, 14)},
     6: {'engine': Fr(405993, 153725), 'widened': Fr(63, 31)},
     7: {'engine': None, 'widened': None},
     8: {'engine': None, 'widened': None}}

def ceil_fr(x): return -((-x.numerator) // x.denominator)

def partC():
    print("C. units open under the certified rung-1 bound and closed by Theorem D (total rank >= W + m - 1)")
    for m in range(2, 9):
        for game in ('engine', 'widened'):
            Lm = L[m][game]
            rows = []
            for W in range(1, 13):
                old = ceil_fr(W * Lm) if Lm is not None else W        # W: trivial bound if nothing certified
                new = max(old, W + m - 1)
                for M in range(old, min(new, m * W)):
                    rows.append(f"{W}-in-{M} ({math.log(m * W / M) / math.log(m):.3f})")
            Ls = f"{float(Lm):.4f}" if Lm is not None else "none certified"
            print(f"  block {m} {game:7s} (L = {Ls}): newly excluded: {', '.join(rows) if rows else 'none'}")
    print("  smallest open units after Theorem D (W <= 6; '-' = none with M < mW):")
    for m in range(3, 7):
        for game in ('engine', 'widened'):
            Lm = L[m][game]; out = []
            for W in range(1, 7):
                M = max(ceil_fr(W * Lm), W + m - 1)
                out.append(f"{W}-in-{M} ({math.log(m * W / M) / math.log(m):.3f})" if M < m * W else f"{W}: -")
            print(f"    block {m} {game:7s}: {'; '.join(out)}")

def partD():
    print("D. barriers")
    targets = [(3, 5, 14), (3, 6, 17), (4, 2, 7), (4, 3, 10), (4, 4, 13), (4, 5, 16), (5, 3, 7), (5, 2, 6),
               (6, 3, 8), (6, 4, 9)]
    print("  filtered rung with level j >= 1 can exclude W-in-M only if j + W*(m-j) > M for some j (s_j <= m-j):")
    for m, W, M in targets:
        js = [j for j in range(1, m) if j + W * (m - j) > M]
        print(f"    block {m}, {W}-in-{M}: levels that could help: {js if js else 'none -> filtered rung = rung 1'}")
    print("  pair (two-register) potential, generator counting: per-array ceiling sqrt(2m+1)-1 vs plain m:")
    for m in range(2, 9):
        print(f"    m={m}: {math.sqrt(2 * m + 1) - 1:.4f}  (block-2 test needs 2: {'FAILS' if m == 2 else ''})")

if __name__ == '__main__':
    partA(); partB(); partC(); partD()
